export const interviewPacks = Object.freeze(Object.keys(packs));
export function interviewQuestions(pack, language) {
  const index = {en: 1, es: 2, ja: 3}[String(language).slice(0, 2)] || 0;
  const packLevels = levels[pack] || [];
  return (packs[pack] || []).map((row, i) => ({
    prompt: row[index],
    reference: references[pack]?.[i]?.[index] || '',
    level: packLevels[i] || (i < 2 ? 'levelBasic' : i < 4 ? 'levelPractical' : 'levelComplex'),
  }));
}

// Indices identify a case and its follow-up within the same editorial pack.
const casePairs = {
  general: [[0, 5], [2, 4]], first: [[0, 4], [1, 5]],
  behavioral: [[0, 5], [1, 6]], support: [[0, 4], [3, 5]], sheets: [[0, 4], [2, 5]],
};

function pairsFor(pack) {
  return casePairs[pack] || [[0, 1], [2, 3]];
}

export function followsCase(first, second, language) {
  return interviewPacks.some(pack => {
    const bank = interviewQuestions(pack, language);
    return pairsFor(pack).some(([a, b]) => bank[a].prompt === first && bank[b].prompt === second);
  });
}

export function interviewTemplate(pack, language, sessions = []) {
  const general = interviewQuestions('general', language);
  const behavior = interviewQuestions('behavioral', language);
  const bank = interviewQuestions(pack, language);
  // Prefer less practised material. Previewing a model does not affect its order.
  const usage = new Map();
  for (const session of sessions) {
    for (const attempt of session.attempts) {
      const prompt = session.questions.find(q => q.id === attempt.questionId)?.prompt;
      if (prompt && attempt.result === 'answered') usage.set(prompt, (usage.get(prompt) || 0) + 1);
    }
  }
  const count = q => usage.get(q.prompt) || 0;
  const prefer = candidates => candidates.reduce((a, b) => count(a) <= count(b) ? a : b);
  const cases = pack === 'general' ? behavior : bank;
  const pair = pairsFor(pack === 'general' ? 'behavioral' : pack)
    .map(([a, b]) => [cases[a], cases[b]])
    .reduce((a, b) => count(a[0]) + count(a[1]) <= count(b[0]) + count(b[1]) ? a : b);
  return [prefer([general[1], general[0]]), prefer([general[6], general[7]]), ...pair,
    prefer([general[8], general[5]])];
}
